    "id": "pattern.starter",
    "kind": "pattern",
    "title": "Starter: React app, Node API, PostgreSQL",
    "summary": "The smallest complete web application. A React app in the browser, one Node.js API, and one PostgreSQL database that only the API touches.",
    "level": "beginner",
